function splitIntoChunks(totalMs, chunkMs) {
  const chunks = [];
  let remaining = totalMs;
  while (remaining > 0) {
    const chunk = Math.min(chunkMs, remaining);
    chunks.push(chunk);
    remaining -= chunk;
  }
  return chunks;
}

